-- 에스컬레이터 연혁: 표·그림 첨부 반영 (v2 배포 이후 실행)
-- 1) attachments/attachments_text 컬럼 추가  2) 본문에서 표·그림 글자 제거(첨부로 이동)  3) 5.12.2.7.4~6 신규 6행 + 표 첨부
-- 안전장치: 수정 대상 행의 본문이 v2 배포본과 정확히 같을 때만 갱신하고, 건수가 다르면 전체 롤백합니다.
-- 코드 배포 전에 먼저 실행해야 합니다(새 컬럼을 앱이 조회).
\set ON_ERROR_STOP on
BEGIN;
ALTER TABLE public.inspection_item_revisions ADD COLUMN IF NOT EXISTS attachments jsonb;
ALTER TABLE public.inspection_item_revisions ADD COLUMN IF NOT EXISTS attachments_text text;
CREATE TEMP TABLE _upd (item_id text, typ text, eff text, exp text, old_md5 text, new_descr text, att jsonb, atxt text) ON COMMIT DROP;
INSERT INTO _upd VALUES ('5.4.2.1.3.1','current','2022-03-02',NULL,'63c98c4778e624ff102ccb48040f7dc7','5.4.2.1.3.1 에스컬레이터의 제동부하 결정
표 2는 에스컬레이터의 제동부하 결정에 적용되어야 한다.
표 2. 에스컬레이터의 제동부하 결정에 고려되는 스텝의 수량은”층고 h₁₃을 스텝 라이저의 최대 외관 높이로 나눈 값”에 의해 결정된다.(그림 8의 x₁ 참조)
시험의 목적을 위해, 총 제동부하는 이렇게 얻어진 스텝 수량의 2/3 이상 분포되는 것을 허용한다.','[{"kind": "table", "caption": "표 2 ― 에스컬레이터의 제동부하 결정", "images": [], "table": {"rows": [[{"t": "공칭 폭 z₁", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "스텝 당 제동부하", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 이하", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "60 ㎏", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 초과 0.8 m 이하", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "90 ㎏", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.8m 초과 1.1 m 이하", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "120 ㎏", "r": 3, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 2 ― 에스컬레이터의 제동부하 결정 공칭 폭 z₁ 스텝 당 제동부하 0.6 m 이하 60 ㎏ 0.6 m 초과 0.8 m 이하 90 ㎏ 0.8m 초과 1.1 m 이하 120 ㎏"}]'::jsonb,'표 2 ― 에스컬레이터의 제동부하 결정 공칭 폭 z₁ 스텝 당 제동부하 0.6 m 이하 60 ㎏ 0.6 m 초과 0.8 m 이하 90 ㎏ 0.8m 초과 1.1 m 이하 120 ㎏');
INSERT INTO _upd VALUES ('5.4.2.1.3.1','old','2013-09-15','2022-03-01','d624961408a6c3961db00f1a7320c20c','5.4.2.1.3.1 에스컬레이터의 제동부하 결정
표 1은 에스컬레이터의 제동부하 결정에 적용되어야 한다.
고려되는 스텝의 수량은 “스텝 라이저의 최대 외관 높이로 나눈 높이 h13”에 의해 결정된다.(그림 5의 x1 참조) 시험의 목적을 위해, 총 제동부하는 이렇게 얻어진 스텝 수량의 2/3 이상 분포되는 것을 허용한다.','[{"kind": "table", "caption": "표 1 - 에스컬레이터의 제동부하 결정", "images": [], "table": {"rows": [[{"t": "공칭 폭 Z₁", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "스텝 당 제동부하", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 이하", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "60 kg", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 초과 0.8 m 이하", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "90 kg", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.8 m 초과 1.1 m 이하", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "120 kg", "r": 3, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 1 - 에스컬레이터의 제동부하 결정 공칭 폭 Z₁ 스텝 당 제동부하 0.6 m 이하 60 kg 0.6 m 초과 0.8 m 이하 90 kg 0.8 m 초과 1.1 m 이하 120 kg"}]'::jsonb,'표 1 - 에스컬레이터의 제동부하 결정 공칭 폭 Z₁ 스텝 당 제동부하 0.6 m 이하 60 kg 0.6 m 초과 0.8 m 이하 90 kg 0.8 m 초과 1.1 m 이하 120 kg');
INSERT INTO _upd VALUES ('5.4.2.1.3.2','current','2022-03-02',NULL,'617154c1e0b9bb698d2591d0e8866fd9','5.4.2.1.3.2 에스컬레이터의 정지거리
무부하 상승, 무부하 하강 및 부하 상태(5.4.2.1.3.1 참조) 하강에 대한 에스컬레이터 정지거리는 표 3에 따라야 한다.
공칭속도 사이에 있는 속도의 정지거리는 보간법으로 결정되어야 한다. 정지거리는 전기적 정지장치가 작동된 시간부터 측정되어야 한다.
하강방향으로 움직이는 에스컬레이터에서 측정된 감속도는 브레이크 시스템이 작동 하는

동안 1 ㎨ 이하이어야 한다.
측정 목적을 위해, 측정 감속신호는 4 ㎐ 이하 통과 2극 버터워스 필터를 사용하여 대역이 제한되어야 한다.
비고 주어진 감속제한 내에서 가능한 가장 짧은 정지거리가 이뤄지는 것이 추천된다.','[{"kind": "table", "caption": "표 3 ― 에스컬레이터의 정지거리", "images": [], "table": {"rows": [[{"t": "공칭속도 v", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정지거리", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.50 ㎧", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "0.20 m부터 1.00 m까지", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.65 ㎧", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "0.30 m부터 1.30 m까지", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.75 ㎧", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "0.40 m부터 1.50m까지", "r": 3, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 3 ― 에스컬레이터의 정지거리 공칭속도 v 정지거리 0.50 ㎧ 0.20 m부터 1.00 m까지 0.65 ㎧ 0.30 m부터 1.30 m까지 0.75 ㎧ 0.40 m부터 1.50m까지"}]'::jsonb,'표 3 ― 에스컬레이터의 정지거리 공칭속도 v 정지거리 0.50 ㎧ 0.20 m부터 1.00 m까지 0.65 ㎧ 0.30 m부터 1.30 m까지 0.75 ㎧ 0.40 m부터 1.50m까지');
INSERT INTO _upd VALUES ('5.4.2.1.3.2','old','2013-09-15','2022-03-01','daccdd73e739676a4ccc394376739639','5.4.2.1.3.2 에스컬레이터의 정지거리
무부하 상태의 에스컬레이터 및 하강 방향으로 움직이는 제동부하 상태(5.4.2.1.3.1 참조)의 에스컬레이터에 대한 정지거리는 표 2에 따라야 한다.
공칭속도 사이에 있는 속도의 정지거리는 보간법으로 결정되어야 한다.
정지거리는 전기적 정지장치가 작동된 시간부터 측정되어야 한다.
운행방향에서 하강방향으로 움직이는 에스컬레이터에서 측정된 감속도는 브레이크 시스템이 작동하는 동안 1 ㎨ 이하이어야 한다. 원 감속신호는 4 Hz 2극 버터워스 필터를 사용하는 대역제한신호이어야 한다.
비고 주어진 감속제한 내에서 가능한 가장 짧은 정지거리가 이뤄지는 것이 추천된다.','[{"kind": "table", "caption": "표 2 - 에스컬레이터의 정지거리", "images": [], "table": {"rows": [[{"t": "공칭속도 V", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정지거리", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.50 ㎧", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "0.20 m에서 1.00 m 사이", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.65 ㎧", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "0.30 m에서 1.30 m 사이", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.75 ㎧", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "0.40 m에서 1.50 m 사이", "r": 3, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 2 - 에스컬레이터의 정지거리 공칭속도 V 정지거리 0.50 ㎧ 0.20 m에서 1.00 m 사이 0.65 ㎧ 0.30 m에서 1.30 m 사이 0.75 ㎧ 0.40 m에서 1.50 m 사이"}]'::jsonb,'표 2 - 에스컬레이터의 정지거리 공칭속도 V 정지거리 0.50 ㎧ 0.20 m에서 1.00 m 사이 0.65 ㎧ 0.30 m에서 1.30 m 사이 0.75 ㎧ 0.40 m에서 1.50 m 사이');
INSERT INTO _upd VALUES ('5.4.2.1.3.3','current','2022-03-02',NULL,'a476fea6bdb0baa4fc0416a54805d542','5.4.2.1.3.3 무빙워크의 제동부하 결정

표 4는 무빙워크의 제동부하 결정에 적용되어야 한다.
여러 개의 경사(층고 차이)를 갖는 무빙워크 길이에 대한 제동부하 결정은 하강 운행부분만 고려되어야 한다.','[{"kind": "table", "caption": "표 4 ― 무빙워크의 제동부하 결정", "images": [], "table": {"rows": [[{"t": "공칭 폭 z₁", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "0.4 m 길이 당 제동부하", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 이하", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "50 ㎏", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 초과 0.8 m 이하", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "75 ㎏", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.8 m 초과 1.1 m 이하", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "100 ㎏", "r": 3, "c": 1, "rs": 1, "cs": 1}], [{"t": "1.10 m 초과 1.40 m 이하", "r": 4, "c": 0, "rs": 1, "cs": 1}, {"t": "125 ㎏", "r": 4, "c": 1, "rs": 1, "cs": 1}], [{"t": "1.40 m 초과 1.65 m 이하", "r": 5, "c": 0, "rs": 1, "cs": 1}, {"t": "150 ㎏", "r": 5, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 4 ― 무빙워크의 제동부하 결정 공칭 폭 z₁ 0.4 m 길이 당 제동부하 0.6 m 이하 50 ㎏ 0.6 m 초과 0.8 m 이하 75 ㎏ 0.8 m 초과 1.1 m 이하 100 ㎏ 1.10 m 초과 1.40 m 이하 125 ㎏ 1.40 m 초과 1.65 m 이하 150 ㎏"}]'::jsonb,'표 4 ― 무빙워크의 제동부하 결정 공칭 폭 z₁ 0.4 m 길이 당 제동부하 0.6 m 이하 50 ㎏ 0.6 m 초과 0.8 m 이하 75 ㎏ 0.8 m 초과 1.1 m 이하 100 ㎏ 1.10 m 초과 1.40 m 이하 125 ㎏ 1.40 m 초과 1.65 m 이하 150 ㎏');
INSERT INTO _upd VALUES ('5.4.2.1.3.3','old','2013-09-15','2022-03-01','6176f1f550e7e62cfe3166918c09de47','5.4.2.1.3.3 무빙워크의 제동부하 결정
표 3은 무빙워크의 제동부하 결정에 적용되어야 한다.
여러 개의 경사(다른 수준)를 갖는 무빙워크의 제동부하 결정은 하강운행 부분만 고려되어야 한다.','[{"kind": "table", "caption": "표 3 - 무빙워크의 제동부하 결정", "images": [], "table": {"rows": [[{"t": "공칭 폭 Z₁", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "0.4 m 길이 당 제동부하", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 이하", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "50 kg", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.6 m 초과 0.8 m 이하", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "75 kg", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.8 m 초과 1.1 m 이하", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "100 kg", "r": 3, "c": 1, "rs": 1, "cs": 1}], [{"t": "1.10 m 초과 1.40 m 이하", "r": 4, "c": 0, "rs": 1, "cs": 1}, {"t": "125 kg", "r": 4, "c": 1, "rs": 1, "cs": 1}], [{"t": "1.40 m 초과 1.65 m 이하", "r": 5, "c": 0, "rs": 1, "cs": 1}, {"t": "150 kg", "r": 5, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 3 - 무빙워크의 제동부하 결정 공칭 폭 Z₁ 0.4 m 길이 당 제동부하 0.6 m 이하 50 kg 0.6 m 초과 0.8 m 이하 75 kg 0.8 m 초과 1.1 m 이하 100 kg 1.10 m 초과 1.40 m 이하 125 kg 1.40 m 초과 1.65 m 이하 150 kg"}]'::jsonb,'표 3 - 무빙워크의 제동부하 결정 공칭 폭 Z₁ 0.4 m 길이 당 제동부하 0.6 m 이하 50 kg 0.6 m 초과 0.8 m 이하 75 kg 0.8 m 초과 1.1 m 이하 100 kg 1.10 m 초과 1.40 m 이하 125 kg 1.40 m 초과 1.65 m 이하 150 kg');
INSERT INTO _upd VALUES ('5.4.2.1.3.4','current','2022-03-02',NULL,'718a68d7117c316feb8f5f799396f70b','5.4.2.1.3.4 무빙워크의 정지거리
무부하 상승, 무부하 하강 및 부하 상태(5.4.2.1.3.3 참조) 하강에 대한 경사형 무빙워크 정지거리는 표 5에 따라야 한다.
이는 무부하 및 부하상태의 양방향에 대한 수평형 무빙워크에도 적용된다.
공칭 속도 사이에 있는 속도의 정지거리는 보간법으로 결정되어야 한다.
정지거리는 전기적 정지장치가 작동된 시간부터 측정되어야 한다.
운행방향에서 하강방향으로 움직이거나 또는 수평으로 움직이는 무빙워크에서 측정된 감속도는 브레이크 시스템이 작동하는 동안 1 ㎨ 이하이어야 한다.
측정 목적을 위해 측정 감속신호는 4 ㎐ 이하 통과 2극 버터워스 필터를 사용하여 대역이 제한되어야 한다.
비고 무빙워크 제동시험은 무부하로 충분하며, 주어진 감속제한 내에서 가능한 가장 짧은 정지거리가 되는 것을 추천한다.
무빙워크의 경우 제조사는 부하 상태의 정지거리를 계산으로 증명해야 한다.','[{"kind": "table", "caption": "표 5 ― 무빙워크의 정지거리", "images": [], "table": {"rows": [[{"t": "공칭속도 v", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정지거리", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.50 ㎧", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "0.20 m부터 1.00 m까지", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.65 ㎧", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "0.30 m부터 1.30 m까지", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.75 ㎧", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "0.40 m부터 1.50 m까지", "r": 3, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.90 ㎧", "r": 4, "c": 0, "rs": 1, "cs": 1}, {"t": "0.55 m부터 1.70 m까지", "r": 4, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 5 ― 무빙워크의 정지거리 공칭속도 v 정지거리 0.50 ㎧ 0.20 m부터 1.00 m까지 0.65 ㎧ 0.30 m부터 1.30 m까지 0.75 ㎧ 0.40 m부터 1.50 m까지 0.90 ㎧ 0.55 m부터 1.70 m까지"}]'::jsonb,'표 5 ― 무빙워크의 정지거리 공칭속도 v 정지거리 0.50 ㎧ 0.20 m부터 1.00 m까지 0.65 ㎧ 0.30 m부터 1.30 m까지 0.75 ㎧ 0.40 m부터 1.50 m까지 0.90 ㎧ 0.55 m부터 1.70 m까지');
INSERT INTO _upd VALUES ('5.4.2.1.3.4','old','2013-09-15','2022-03-01','32684fb2c79b7a152759d21409d225b5','5.4.2.1.3.4 무빙워크의 정지거리
무부하 상태의 무빙워크 및 수평 또는 하강 방향으로 움직이는 제동부하 상태(5.4.2.1.3.3 참조)의 무빙워크에 대한 정지거리는 표 4에 따라야 한다.
공칭속도 사이에 있는 속도의 정지거리는 보간법으로 결정되어야 한다.
정지거리는 전기적 정지장치가 작동된 시간부터 측정되어야 한다.
운행방향에서 하강방향으로 움직이거나 또는 수평으로 움직이는 무빙워크에서 측정된 감속도는 브레이크 시스템이 작동하는 동안 1 ㎨ 이하이어야 한다. 원 감속신호는 4 Hz 2극 버터워스 필터를 사용하는 대역제한신호이어야 한다.
비고 무빙워크 제동시험은 무부하로 충분하며, 주어진 감속제한 내에서 가능한 가장 짧은 정지거리가 되는 것을 추천한다.','[{"kind": "table", "caption": "표 4 무빙워크의 정지거리", "images": [], "table": {"rows": [[{"t": "공칭속도 V", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "정지거리", "r": 0, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.50 ㎧", "r": 1, "c": 0, "rs": 1, "cs": 1}, {"t": "0.20 m에서 1.00 m 사이", "r": 1, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.65 ㎧", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "0.30 m에서 1.30 m 사이", "r": 2, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.75 ㎧", "r": 3, "c": 0, "rs": 1, "cs": 1}, {"t": "0.40 m에서 1.50 m 사이", "r": 3, "c": 1, "rs": 1, "cs": 1}], [{"t": "0.90 ㎧", "r": 4, "c": 0, "rs": 1, "cs": 1}, {"t": "0.55 m에서 1.70 m 사이", "r": 4, "c": 1, "rs": 1, "cs": 1}]], "ncols": 2}, "search": "표 4 무빙워크의 정지거리 공칭속도 V 정지거리 0.50 ㎧ 0.20 m에서 1.00 m 사이 0.65 ㎧ 0.30 m에서 1.30 m 사이 0.75 ㎧ 0.40 m에서 1.50 m 사이 0.90 ㎧ 0.55 m에서 1.70 m 사이"}]'::jsonb,'표 4 무빙워크의 정지거리 공칭속도 V 정지거리 0.50 ㎧ 0.20 m에서 1.00 m 사이 0.65 ㎧ 0.30 m에서 1.30 m 사이 0.75 ㎧ 0.40 m에서 1.50 m 사이 0.90 ㎧ 0.55 m에서 1.70 m 사이');
INSERT INTO _upd VALUES ('5.5.3.4','current','2022-03-02',NULL,'83ad2b34632f1120a73846209b4f825d','5.5.3.4 에스컬레이터는 스커트와 스텝 사이에 끼일 가능성이 최소화 되어야 한다.
이 목적을 위해 다음 4가지 조건이 충족되어야 한다.
가) 5.5.3.3에 따른 스커트의 충분한 강도
나) 5.5.5.1에 따른 틈새
다) 아래의 사항을 만족하는 스커트 디플렉터의 설치
1) 견고한 부분과 유연한 부분(브러시 또는 고무 재질 등)으로 구성되어야 한다.
2) 스커트 패널의 수직면으로부터 수평방향으로 최소 33 ㎜, 최대 50 ㎜ 돌출되어야 한다.
3) 견고한 부분의 돌출된 지점에 600 ㎟의 직사각형 면적 위로 견고한 부분의 부착 선상에 수직으로 균등 분포된 900 N의 힘을 가할 때 떨어지거나 영구적인 변형 없이 견뎌야 한다.
4) 견고한 부분은 18 ㎜와 25 ㎜ 사이의 수평 돌출부가 있어야 하고, 규정된 강도를 견뎌야 한다. 유연한 부분의 수평 돌출부는 최소 15 ㎜, 최대 30 ㎜ 이어야 한다.
5) 경사구간에서 스커트 디플렉터의 견고한 부분의 아래쪽 가장 낮은 부분과 스텝 앞부분(step nose) 사이의 수직거리는 25 ㎜와 30 ㎜ 사이이어야 한다.
6) 천이구간 및 수평구간에서 스커트 디플렉터의 견고한 부분의 아래쪽 가장 낮은 부분과 스텝 클리트의 꼭대기 사이의 거리는 25 ㎜와 55 ㎜ 사이이어야 한다.
7) 스커트 패널 수직면에 대해 견고한 부분의 하부표면은 위로 25 °이상 경사져야하고 상부 표면은 아래로 25 °이상 경사져야 한다.
8) 그림 3 가)와 달리, 견고한 부분의 상부에서는 아래로 하부에서는 위로 볼록한 경사면을 갖는 스커트에 수직인 폭 5 ㎜ 이하의 평평한 표면이 제공되는 것은 허용된다. 형상은 견고한 부분을 수평투영한 길이의 절반 이상은 25 °경사도를 가져야 한다.[그림 3 나)]
9) 견고한 부분의 경사면이 25 °이상의 직선 기울기를 갖고 스커트에 수직방향으로 평평한 표면이 있는 경우 그 폭은 상부 10 ㎜ 이하, 하부 5 ㎜ 이하까지 허용된다.[그림 3 다)]
10) 스커트 디플렉터는 모서리가 둥글게 설계되어야 한다. 고정장치 헤드 및 접합 연결부는 운행경로로 연장되지 않아야 한다.
11) 스커트 디플렉터의 말단 끝부분은 스커트와 동일 평면에 마감되도록 점점 가늘어져야 한다. 스커트 디플렉터의 말단 끝부분은 콤 교차선에서 최소 50 ㎜ 이

상, 최대 150 ㎜ 앞에서 마감되어야 한다.
12) 스커트 디플렉터가 하부 내측데크 연장일 경우에는 5.5.2.6.2가 적용된다. 스커트 디플렉터가 스커트에 부착되거나 스커트의 구성부품인 경우에는 5.5.3.1이 적용된다.
라) 시험용 윤활제를 이용한 고무 마찰계수를 0.45보다 작게 하기 위하여 디플렉터 아래에 적합한 재질 또는 적합한 형식의 안감 사용. 이 고무는 SBR 생고무, 미네랄 충전재, 가공 첨가제, 밀도가 (1.23 ± 0.2) g/㎤인 가교 결합제 및 KS M ISO 868에 따른 쇼어 D-경도가 50 ± 3인 SBR 고무로 정의된다.
시험용 윤활제는 황산 도데실 나트륨(순도 ≥ 99 %) 탈이온수 또는 증류수로 구성된 용액으로 정의된다. (시험방법에 대한 정보는 부속서 Ⅸ 참조)','[{"kind": "figure", "caption": "그림 3 ― 스커트 디플렉터에 대한 기준", "images": ["5.5.3.4_current_cur_f1_0.png", "5.5.3.4_current_cur_f1_1.png"], "table": null, "search": "그림 3 스커트 디플렉터에 대한 기준 가) 나) 다) 기호설명 1 유연한 부분 2 견고한 부분 a 경사 구간 b 천이 및 수평 구간 비고 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준을 설명한다."}]'::jsonb,'그림 3 스커트 디플렉터에 대한 기준 가) 나) 다) 기호설명 1 유연한 부분 2 견고한 부분 a 경사 구간 b 천이 및 수평 구간 비고 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준을 설명한다.');
INSERT INTO _upd VALUES ('5.5.3.4','old','2013-09-15','2022-03-01','6587c62dc37673bbd8f832c323a5bce9','5.5.3.4 에스컬레이터는 스커트와 스텝 사이에 끼일 가능성이 최소화 되어야 한다.
이 목적을 위해 다음 4가지 사항에 적합하여야 한다.
가) 5.5.3.3에 따른 스커트의 충분한 강도
나) 5.5.5.1에 따른 틈새
다) 아래의 사항을 만족하는 스커트 디플렉터의 설치
1) 견고한 부분과 유연한 부분(브러시 또는 고무 등)으로 구성되어야 한다.
2) 스커트 패널의 수직면 돌출부는 최소 33 mm, 최대 50 mm이어야 한다.
3) 견고한 부분의 부착물 선상에 수직으로 견고한 부분의 돌출된 지점에 600 ㎟의 직사각형 면적 위로 균등하게 분포된 900 N의 힘을 가할 때 떨어지거나 영구적인 변형 없이 견뎌야 한다.
4) 견고한 부분은 18 mm와 25 mm 사의 수평 돌출부가 있어야 하고, 규정된 강도를 견뎌야 한다. 유연한 부분의 수평 돌출부는 최소 15 mm, 최대 30 mm 이어야 한다.
5) 주행로의 경사진 구간의 전체에 걸쳐 스커트 디플렉터의 견고한 부분의 아래 쪽 가장 낮은 부분과 스텝 돌출부 선상 사이의 수직거리는 25 mm와 27 mm 사이이어야 한다.
6) 천이구간 및 수평구간에서 스커트 디플렉터의 견고한 부분의 아래 쪽 가장 낮은 부분과 스텝 클리트의 꼭대기 사이의 거리는 25 mm와 50 mm 사이이어야 한다.
7) 견고한 부분의 하부표면은 스커트 패널로부터 상승방향으로 25°이상 경사져야하고 상부표면은 하강방향으로 25°이상 경사져야 한다.
8) 스커트 디플렉터는 모서리가 둥글게 설계되어야 한다. 고정 장치 헤드 및 접합 연결부는 운행통로로 연장되지 않아야 한다.
9) 스커트 디플렉터의 말단 끝 부분은 스커트와 동일 평면에 접촉되도록 점점 가늘어져야 한다. 스커트 디플렉터의 말단 끝부분은 콤 교차선에서 최소 50mm 이상, 최대 150mm 앞에서 마감되어야 한다.
10) 스커트 디플렉터가 하부 내측 데크의 범위까지 확장될 경우에는 5.5.2.6.2가 적용된다.
11) 스커트 디플렉터가 스커트에 부착되거나 스커트의 구성부품인 경우에는 5.5.3.1이 적용된다.
라) 가죽(젖고 마른), PVC(마른) 및 고무(마른)의 마찰계수를 0.45보다 작게 하기위해 디플렉터 아래에 적합한 재질 또는 적합한 형식의 안감 사용
[승강기 검사기준] 부칙 <시행 2015. 5. 13.>
제3조(경과조치)
③ 제1항에 불구하고 이 고시 시행 전에 종전의 검사기준을 적용하여 검사를 받고 사용 중인 에스컬레이터의 경우 이 고시 시행일로부터 1년 이내에 [별표 3] 5.5.3.4 다)에 적합한 스커트 디플렉터를 설치하여야 한다. 다만, 이 고시 시행일 이전에 설치된 스커트 디플렉터의 경우 이 고시에 의해 설치된 것으로 본다.','[{"kind": "figure", "caption": "그림 1 스커트 디플렉터의 요건", "images": ["5.5.3.4_old_2013-09-15_f1_0.png"], "table": null, "search": "그림 1 스커트 디플렉터의 요건 단위 : mm Key 1. 유연한 부분 2. 견고한 부분 a 경사진 지역 b 천이구간 및 수평구간"}]'::jsonb,'그림 1 스커트 디플렉터의 요건 단위 : mm Key 1. 유연한 부분 2. 견고한 부분 a 경사진 지역 b 천이구간 및 수평구간');
INSERT INTO _upd VALUES ('5.8.2.1','current','2022-03-02',NULL,'96f9b89ee0de52574b6487de929a2c0b','5.8.2.1 기계류 공간 내부(특히, 트러스)의 구동ㆍ순환 장소에서 충분히 서 있을 수 있는 공간은 영구적으로 설치된 부품으로부터 자유로워야 한다.
서 있을 수 있는 면적의 크기는 0.3 m2 이상이고 작은 변의 길이는 0.5 m 이상이어야 한다. 단, 영구적으로 설치된 부품이 최대 반경 0.25 m의 둥근 모서리 뒤에 위치하고 서 있을 수 있는 면적 위로 0.12 m 이상 높이 위치하는 경우, 이 공간에 영구적으로 설치된 부품을 둘 수 있다.(그림 4 참조)','[{"kind": "figure", "caption": "그림 4 ― 서 있을 수 있는 공간", "images": ["5.8.2.1_current_cur_f1_0.png"], "table": null, "search": "그림 4 서 있을 수 있는 공간 r max ≈ 0,25 ≥0,5 ≥0,3 m²"}]'::jsonb,'그림 4 서 있을 수 있는 공간 r max ≈ 0,25 ≥0,5 ≥0,3 m²');
INSERT INTO _upd VALUES ('5.12.3.8.1','current','2022-03-02',NULL,'40317437ced8c4023e220bbd3bbac325','5.12.3.8.1 정지장치의 액추에이터가 작동될 때, 5.12.2.7.15에 따라 비상상황 시 에스컬레이터 또는 무빙워크를 정지시키기 위한 비상정지장치를 설치해야 한다.
정지장치의 액추에이터는 에스컬레이터 또는 무빙워크의 각 승강장 또는 승강장 근처에 눈에 뛰고 쉽게 접근할 수 있는 위치에 있어야 한다.(6.1.2.2 참조)
승강장에서, 정지 스위치는 디딤판 바깥 구역에서 접근 가능해야 한다.
정지 스위치가 난간 높이 h1의 중간 이하에 위치하는 경우, 그림 12에 따른 다음 특징을 가진 표시가 난간의 안쪽에 위치해야 한다.
- 지름 80 ㎜ 이상
- 적색
- 흰색 글씨로”정지”(필요시 다른 언어 병기 가능)라고 표시
- 난간 높이 h1의 중간 이상에 위치
- 정지장치를 가리키는 화살표(난간 높이 h1의 중간 이하에 위치할 수도 있음) 비상정지장치 사이의 거리는 다음과 같아야 한다.
- 에스컬레이터의 경우에는 30 m 이하이어야 한다.
- 무빙워크의 경우에는 40 m 이하이어야 한다.
필요한 경우 추가적인 정지장치는 거리를 유지하도록 설치되어야 한다.','[{"kind": "figure", "caption": "그림 12. 정지 장치 표시 예", "images": ["5.12.3.8.1_current_cur_f1_0.png"], "table": null, "search": "그림 12 정지 장치 표시 예 치수 (㎜) ≥Ø80 정지 비고 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준을 설명한다."}]'::jsonb,'그림 12 정지 장치 표시 예 치수 (㎜) ≥Ø80 정지 비고 이 그림은 일정한 비율로 그려져 있지 않고 단지 기준을 설명한다.');
INSERT INTO _upd VALUES ('6.1.2.1','current','2022-03-02',NULL,'6467bbf55ea4c1987be7988f63f03110','6.1.2.1 주의표시를 위한 표시판 또는 표지는 견고한 재질로 만들어야 하며, 승강장에서 잘 보이는 곳에 확실히 부착되어야 한다.
주의표시는 80 ㎜ × 100 ㎜ 이상의 크기로 그림과 같이 표시되어야 한다.
비고 상기의 주의표시이외에 부속서 Ⅴ의 주의표시를 추가로 부착할 수 있다.','[{"kind": "figure", "caption": "그림 13. 에스컬레이터 또는 무빙워크 출입구 근처의 주의표시", "images": ["6.1.2.1_current_cur_f1_0.png"], "table": null, "search": "그림 13 에스컬레이터 또는 무빙워크 출입구 근처의 주의표시 안전 손잡이를 꼭 잡으세요 추락 우려가 있습니다 위험 걷거나 뛰지 마세요 넘어질 위험이 있습니다 안전 어린이나 노약자는 보호자와 함께 이용하세요 사고위험이 있습니다 안전 안전선 안에 서 주세요 발가락 등이 끼일 염려가 있습니다"}, {"kind": "table", "caption": "", "images": [], "table": {"rows": [[{"t": "구 분", "r": 0, "c": 0, "rs": 1, "cs": 2}, {"t": "기준규격\n(㎜)", "r": 0, "c": 2, "rs": 1, "cs": 1}, {"t": "색 상", "r": 0, "c": 3, "rs": 1, "cs": 1}], [{"t": "최소 크기", "r": 1, "c": 0, "rs": 1, "cs": 2}, {"t": "80 × 100", "r": 1, "c": 2, "rs": 1, "cs": 1}, {"t": "-", "r": 1, "c": 3, "rs": 1, "cs": 1}], [{"t": "바탕", "r": 2, "c": 0, "rs": 1, "cs": 2}, {"t": "-", "r": 2, "c": 2, "rs": 1, "cs": 1}, {"t": "흰색", "r": 2, "c": 3, "rs": 1, "cs": 1}], [{"t": "", "r": 3, "c": 0, "rs": 4, "cs": 1, "img": "cell_p111_0.png"}, {"t": "원", "r": 3, "c": 1, "rs": 1, "cs": 1}, {"t": "40 × 40", "r": 3, "c": 2, "rs": 1, "cs": 1}, {"t": "-", "r": 3, "c": 3, "rs": 1, "cs": 1}], [{"t": "바탕", "r": 4, "c": 1, "rs": 1, "cs": 1}, {"t": "-", "r": 4, "c": 2, "rs": 1, "cs": 1}, {"t": "황색", "r": 4, "c": 3, "rs": 1, "cs": 1}], [{"t": "사선", "r": 5, "c": 1, "rs": 1, "cs": 1}, {"t": "-", "r": 5, "c": 2, "rs": 1, "cs": 1}, {"t": "적색", "r": 5, "c": 3, "rs": 1, "cs": 1}], [{"t": "도안", "r": 6, "c": 1, "rs": 1, "cs": 1}, {"t": "-", "r": 6, "c": 2, "rs": 1, "cs": 1}, {"t": "흑색", "r": 6, "c": 3, "rs": 1, "cs": 1}], [{"t": "", "r": 7, "c": 0, "rs": 1, "cs": 2, "img": "cell_p111_1.png"}, {"t": "10 × 10", "r": 7, "c": 2, "rs": 1, "cs": 1}, {"t": "녹색(안전)\n황색(위험)", "r": 7, "c": 3, "rs": 1, "cs": 1}], [{"t": "안전, 위험", "r": 8, "c": 0, "rs": 1, "cs": 2}, {"t": "10 × 10", "r": 8, "c": 2, "rs": 1, "cs": 1}, {"t": "흑색", "r": 8, "c": 3, "rs": 1, "cs": 1}], [{"t": "주의\n문구", "r": 9, "c": 0, "rs": 2, "cs": 1}, {"t": "대", "r": 9, "c": 1, "rs": 1, "cs": 1}, {"t": "19 Pt", "r": 9, "c": 2, "rs": 1, "cs": 1}, {"t": "흑색", "r"