INSERT INTO _new VALUES ('5.12.2.7.5','current','2022-03-02',NULL,'5.12.2.7.5 디딤판을 직접 구동하는 부품의 파손 또는 과도한 늘어짐 감지
디딤판을 직접 구동하는 부품(예: 체인 또는 랙)의 파손 또는 과도한 늘어짐을 감지할 수 있는 장치가 제공되어야 한다.',NULL,NULL);
