INSERT INTO _new VALUES ('5.12.2.7.6','current','2022-03-02',NULL,'5.12.2.7.6 인장 장치의 움직임 감지
구동장치와 인장장치 사이의 거리가 20 ㎜를 초과하는 의도되지 않은 연장 또는 감소 움직임을 감지하기 위한 장치가 제공되어야 한다.(5.4.3.3 및 5.4.4.2 참조)',NULL,NULL);
INSERT INTO _new VALUES ('5.12.2.7.6','old','2013-09-15','2022-03-01','표 5 감시 및 전기 안전장치에 대한 규정','[{"kind": "table", "caption": "표 5 감시 및 전기 안전장치에 대한 규정", "images": [], "table": {"rows": [[{"t": "", "r": 0, "c": 0, "rs": 1, "cs": 1}, {"t": "감지되는 상황", "r": 0, "c": 1, "rs": 1, "cs": 1}, {"t": "규정", "r": 0, "c": 2, "rs": 1, "cs": 1}], [{"t": "바)", "r": 2, "c": 0, "rs": 1, "cs": 1}, {"t": "구동 및 순환 장치 사이의 거리의 (의도하지 않은) 연장 또는 감소", "r": 2, "c": 1, "rs": 1, "cs": 1}, {"t": "5.12.1.2.2 또는 5.12.1.2.3", "r": 2, "c": 2, "rs": 1, "cs": 1}]], "ncols": 3}, "search": "표 5 감시 및 전기 안전장치에 대한 규정 감지되는 상황 규정 바) 구동 및 순환 장치 사이의 거리의 (의도하지 않은) 연장 또는 감소 5.12.1.2.2 또는 5.12.1.2.3"}]'::jsonb,'표 5 감시 및 전기 안전장치에 대한 규정 감지되는 상황 규정 바) 구동 및 순환 장치 사이의 거리의 (의도하지 않은) 연장 또는 감소 5.12.1.2.2 또는 5.12.1.2.3');
WITH u AS (UPDATE public.inspection_item_revisions r SET description=x.new_descr, attachments=x.att, attachments_text=x.atxt
  FROM _upd x WHERE r.equipment_type='에스컬레이터' AND r.item_id=x.item_id AND r.introduction_type=x.typ AND r.effective_date=x.eff
  AND r.expiry_date IS NOT DISTINCT FROM x.exp AND md5(r.description)=x.old_md5 RETURNING 1) SELECT count(*) AS updated FROM u \gset
WITH n AS (INSERT INTO public.inspection_item_revisions (item_id,equipment_type,effective_date,expiry_date,introduction_type,description,attachments,attachments_text)
  SELECT item_id,'에스컬레이터',eff,exp,typ,descr,att,atxt FROM _new x WHERE NOT EXISTS (SELECT 1 FROM public.inspection_item_revisions r WHERE r.equipment_type='에스컬레이터' AND r.item_id=x.item_id AND r.introduction_type=x.typ AND r.effective_date=x.eff) RETURNING 1) SELECT count(*) AS inserted FROM n \gset
SELECT :updated AS updated_rows, :inserted AS inserted_rows;
\if `[ :updated -eq 19 ] && [ :inserted -eq 6 ] && echo 1 || echo 0`
  COMMIT;
  \echo '완료'
\else
  ROLLBACK;
  \echo '건수가 맞지 않아 취소했습니다(본문이 v2 배포본과 다르거나 이미 반영됨)'
\endif
